#!/usr/bin/env python3
"""Compute the CSX-176 wildfire smoke-transport score ledger ground truth."""

from __future__ import annotations

import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-176_Q2"
EVENT_ID = "CSX-176"
TARGET_FAMILY = "greece_wildfire_smoke_transport_score_ledger"
EVENT_WINDOW = "2023-08-22_to_2023-08-23"

EVENT_PHRASES = [
    "dozens more fires",
    "alexandroupolis",
    "plume",
    "athens",
    "extreme fire weather",
    "mediterranean sea",
    "effis",
]


RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "Answer schema and classification",
            "points": 3,
            "description": "Returns the requested compact JSON with target_family, event window, signal counts, candidate scores, top candidate, dominance margin, classification = smoke_transport_dominant, and one sentence of interpretation.",
            "partial_credit": "Award partial credit for a complete ledger with minor naming or formatting drift.",
        },
        {
            "name": "Narrative block extraction",
            "points": 4,
            "description": "Identifies the 4 event blocks and derives smoke_blocks = 3, urban_blocks = 1, and fire_weather_blocks = 1.",
            "partial_credit": "Award partial credit for a correct extraction method with one count off by one.",
        },
        {
            "name": "Gate evaluation",
            "points": 4,
            "description": "Sets main_transport_gate = 1, aug23_extent_gate = 1, burn_phrase_gate = 1, and national_burn_value_gate, hospital_or_casualty_value_gate, and drought_index_value_gate to 0.",
            "partial_credit": "Award partial credit for correct positive gates with one mistaken absent numeric-value gate.",
        },
        {
            "name": "Candidate-score arithmetic",
            "points": 4,
            "description": "Applies the formulas to obtain scores of 6, 1, 1, and 1 for smoke transport, national burn severity, national health burden, and the drought-index ledger.",
            "partial_credit": "Award partial credit for correctly identifying the smoke-transport candidate as strongest despite an arithmetic error that changes one secondary score.",
        },
        {
            "name": "Dominance test",
            "points": 3,
            "description": "Computes dominance_margin = 5 and applies the rule that smoke score at least 5 plus margin at least 3 gives smoke_transport_dominant.",
            "partial_credit": "Award partial credit for the correct top candidate without the explicit margin rule.",
        },
        {
            "name": "Concise computed interpretation",
            "points": 2,
            "description": "Ties the interpretation to plume transport, fire weather, and Athens-area urban impact while avoiding added national burn-area, health-burden, casualty, hospital, or drought-index values.",
            "partial_credit": "Award partial credit for a mostly ledger-based interpretation with one minor overstatement.",
        },
    ],
}


def package_dir() -> Path:
    return (
        Path(__file__).resolve().parents[3]
        / "event_packages"
        / "standard_event_packages"
        / "packages"
        / EVENT_ID
    )


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8"))


class BlockParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self._capture = False
        self._buf: list[str] = []
        self.blocks: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"p", "h1", "h2", "h3", "figcaption"}:
            self._capture = True
            self._buf = []

    def handle_endtag(self, tag: str) -> None:
        if tag in {"p", "h1", "h2", "h3", "figcaption"} and self._capture:
            text = " ".join("".join(self._buf).split())
            if text:
                self.blocks.append(text)
            self._capture = False
            self._buf = []

    def handle_data(self, data: str) -> None:
        if self._capture:
            self._buf.append(f" {data} ")


def report_blocks(path: Path) -> list[str]:
    parser = BlockParser()
    parser.feed(path.read_text(encoding="utf-8", errors="ignore"))
    return parser.blocks


def contains_any(text: str, words: list[str]) -> bool:
    lowered = text.lower()
    return any(word in lowered for word in words)


def first_matching(blocks: list[str], pattern: str) -> str:
    rx = re.compile(pattern, re.IGNORECASE)
    for block in blocks:
        if rx.search(block):
            return block
    return ""


def gate(value: bool) -> int:
    return 1 if value else 0


def score_ledger(event_blocks: list[str]) -> dict[str, Any]:
    smoke_blocks = [block for block in event_blocks if contains_any(block, ["smoke", "plume"])]
    urban_blocks = [block for block in event_blocks if contains_any(block, ["homes", "cars", "athens"])]
    fire_weather_blocks = [
        block for block in event_blocks if contains_any(block, ["hot", "dry", "windy"])
    ]

    event_text = " ".join(event_blocks)
    main_transport_gate = gate(
        bool(first_matching(event_blocks, r"Alexandroupolis.*southwest toward Italy"))
    )
    aug23_extent_gate = gate(
        bool(first_matching(event_blocks, r"smoke.*Italy.*Mediterranean Sea.*northern Africa"))
    )
    burn_phrase_gate = gate(contains_any(event_text, ["burned", "burning"]))
    national_burn_value_gate = gate(
        bool(
            re.search(
                r"\b(national|country|nation).{0,80}\b(\d+|thousand|million).{0,80}\b(acres|hectares|square kilometers|burn severity)",
                event_text,
                flags=re.IGNORECASE,
            )
        )
    )
    hospital_or_casualty_value_gate = gate(
        bool(
            re.search(
                r"\b(\d+).{0,80}\b(hospital|hospitalizations|casualties|deaths|fatalities)|\b(hospital|casualties|deaths|fatalities).{0,80}\b(\d+)",
                event_text,
                flags=re.IGNORECASE,
            )
        )
    )
    drought_index_value_gate = gate(
        bool(re.search(r"\b(drought index|spei|spi|pdsi)\b.{0,80}\b\d", event_text, re.IGNORECASE))
    )

    signal_counts = {
        "event_blocks": len(event_blocks),
        "smoke_blocks": len(smoke_blocks),
        "urban_blocks": len(urban_blocks),
        "fire_weather_blocks": len(fire_weather_blocks),
    }

    candidate_scores = {
        "smoke_transport_urban": (
            2 * gate(signal_counts["smoke_blocks"] >= 3)
            + gate(signal_counts["urban_blocks"] >= 1)
            + gate(signal_counts["fire_weather_blocks"] >= 1)
            + main_transport_gate
            + aug23_extent_gate
        ),
        "national_burn_severity": burn_phrase_gate + national_burn_value_gate,
        "national_health_burden": gate(signal_counts["urban_blocks"] >= 1)
        + hospital_or_casualty_value_gate,
        "drought_index_primary": gate(signal_counts["fire_weather_blocks"] >= 1)
        + drought_index_value_gate,
    }

    top_candidate = max(candidate_scores, key=candidate_scores.get)
    top_score = candidate_scores[top_candidate]
    next_best = max(score for name, score in candidate_scores.items() if name != top_candidate)
    dominance_margin = top_score - next_best
    classification = (
        "smoke_transport_dominant"
        if top_candidate == "smoke_transport_urban" and top_score >= 5 and dominance_margin >= 3
        else "not_dominant"
    )

    return {
        "signal_counts": signal_counts,
        "gates": {
            "main_transport_gate": main_transport_gate,
            "aug23_extent_gate": aug23_extent_gate,
            "burn_phrase_gate": burn_phrase_gate,
            "national_burn_value_gate": national_burn_value_gate,
            "hospital_or_casualty_value_gate": hospital_or_casualty_value_gate,
            "drought_index_value_gate": drought_index_value_gate,
        },
        "candidate_scores": candidate_scores,
        "top_candidate": top_candidate,
        "dominance_margin": dominance_margin,
        "classification": classification,
    }


def main() -> None:
    root = package_dir()
    event = read_json(root, "metadata/event.json")
    anchor = read_json(
        root,
        "data/event_reports/event_reports_003_Locked_event_anchor_2023_Greece_wildfires.json",
    )
    report_rel_path = (
        "data/event_reports/event_reports_005_NASA_Earth_Observatory_wildfires_rage_in_Greece.html"
    )
    blocks = report_blocks(root / report_rel_path)
    event_blocks = [block for block in blocks if contains_any(block, EVENT_PHRASES)]
    ledger = score_ledger(event_blocks)
    signal_counts = ledger["signal_counts"]
    candidate_scores = ledger["candidate_scores"]
    answer_ledger = {
        "target_family": TARGET_FAMILY,
        "event_window": EVENT_WINDOW,
        "signal_counts": signal_counts,
        "candidate_scores": candidate_scores,
        "top_candidate": ledger["top_candidate"],
        "dominance_margin": ledger["dominance_margin"],
        "classification": ledger["classification"],
    }
    interpretation = (
        "The August 22-23 ledger is dominated by directly observed plume transport, fire-weather cues, "
        "and Athens-area urban impact signals, while the competing national burn, health, and drought ledgers "
        "lack numeric anchors."
    )

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "answer": answer_ledger,
            "interpretation": interpretation,
        },
        "event": {
            "event_id": EVENT_ID,
            "package_id": event["package_id"],
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "anchor_start": anchor["temporal_window"]["start_date"],
            "anchor_end": anchor["temporal_window"]["end_date"],
        },
        "key_values": {
            "event_phrases": EVENT_PHRASES,
            "signal_counts": signal_counts,
            "gates": ledger["gates"],
            "candidate_scores": candidate_scores,
            "score_formula": {
                "smoke_transport_urban": "2*(smoke_blocks>=3) + (urban_blocks>=1) + (fire_weather_blocks>=1) + main_transport_gate + aug23_extent_gate",
                "national_burn_severity": "burn_phrase_gate + national_burn_value_gate",
                "national_health_burden": "(urban_blocks>=1) + hospital_or_casualty_value_gate",
                "drought_index_primary": "(fire_weather_blocks>=1) + drought_index_value_gate",
                "classification": "smoke_transport_dominant when smoke score >= 5 and dominance margin >= 3",
            },
            "report_anchors": {
                "image_date_and_sensor": first_matching(
                    event_blocks, r"August 22, 2023.*VIIRS.*Suomi NPP"
                ),
                "main_plume": first_matching(
                    event_blocks, r"Alexandroupolis.*southwest toward Italy"
                ),
                "urban_impact": first_matching(event_blocks, r"Athens.*homes.*cars"),
                "fire_weather_and_extent": first_matching(
                    event_blocks, r"extreme fire weather.*Mediterranean Sea"
                ),
            },
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_003_Locked_event_anchor_2023_Greece_wildfires.json",
                report_rel_path,
            ],
            "notes": "Narrative block counts and candidate scores are derived from the local CSX-176 incident report.",
        },
        "rubric": RUBRIC,
    }

    (Path(__file__).resolve().parent / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
